  readonly total: number;
}

import type {
  AttachmentId,
  IsoTimestamp,
  IssueId,
  LabelId,
  ProjectId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type IssueStatus =
  | "backlog"
  | "todo"
  | "in_progress"
  | "in_review"
  | "done"
  | "canceled";

export const ISSUE_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
];

/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/**
 * Groups the `status` filter accepts alongside single statuses (ADR 0009):
 * `open` is every status that is not closed, `closed` the closed ones.
 */
export type IssueStatusGroup = "open" | "closed";

export const ISSUE_STATUS_GROUPS: Readonly<
  Record<IssueStatusGroup, readonly IssueStatus[]>
> = {
  open: ISSUE_STATUSES.filter(
    (status) => !CLOSED_ISSUE_STATUSES.includes(status),
  ),
  closed: CLOSED_ISSUE_STATUSES,
};

/** One value of the `status` filter: a status, or a group standing for several. */
export type IssueStatusFilterValue = IssueStatus | IssueStatusGroup;

export function isIssueStatusGroup(value: string): value is IssueStatusGroup {
  return value === "open" || value === "closed";
}

export function isIssueStatusFilterValue(
  value: string,
): value is IssueStatusFilterValue {
  return (
    isIssueStatusGroup(value) ||
    (ISSUE_STATUSES as readonly string[]).includes(value)
  );
}

/** Replaces every group with its members, keeping first-seen order without repeats. */
export function expandIssueStatuses(
  values: readonly IssueStatusFilterValue[],
): IssueStatus[] {
  const expanded: IssueStatus[] = [];
  for (const value of values) {
    const members = isIssueStatusGroup(value)
      ? ISSUE_STATUS_GROUPS[value]
      : [value];
    for (const status of members) {
      if (!expanded.includes(status)) expanded.push(status);
    }
  }
  return expanded;
}

/** `assignee=none`: issues nobody is assigned to. */
export const UNASSIGNED_TOKEN = "none";

/** `assignee=me` / `author=me`: the signed-in user, resolved by the service. */
export const CURRENT_USER_TOKEN = "me";
export type CurrentUserToken = typeof CURRENT_USER_TOKEN;

export type IssuePriority = "none" | "low" | "medium" | "high" | "urgent";

export const ISSUE_PRIORITIES: readonly IssuePriority[] = [
  "none",
  "low",
  "medium",
  "high",
  "urgent",
];

export interface Issue extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: IssueId;
  readonly projectId: ProjectId;
  readonly number: number;
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly authorId: UserId;
  readonly assigneeId: UserId | null;
  readonly parentId: IssueId | null;
  readonly estimate: number | null;
  readonly dueAt: IsoTimestamp | null;
  readonly startedAt: IsoTimestamp | null;
  readonly completedAt: IsoTimestamp | null;
  readonly labelIds: readonly LabelId[];
}

export interface IssueLabel extends TenantScoped {
  readonly id: LabelId;
  readonly name: string;
  readonly color: string;
  readonly description: string | null;
}

export interface IssueAttachment extends Timestamps, TenantScoped {
  readonly id: AttachmentId;
  readonly issueId: IssueId;
  readonly filename: string;
  readonly contentType: string;
  readonly sizeBytes: number;
  readonly uploadedBy: UserId;
}

/**
 * Filter accepted by the issue repository, service layer and list UI alike.
 * The vocabulary is ADR 0009; omitting a field means "do not filter on it".
 */
export interface IssueFilter {
  readonly projectId?: ProjectId;
  /** Any-of; groups stand for their members. */
  readonly status?: readonly IssueStatusFilterValue[];
  /** Any-of. */
  readonly priority?: readonly IssuePriority[];
  /** A user, `"me"`, or `null` for unassigned issues. */
  readonly assigneeId?: UserId | CurrentUserToken | null;
  readonly authorId?: UserId | CurrentUserToken;
  /** All-of: an issue must carry every listed label. */
  readonly labelIds?: readonly LabelId[];
  readonly query?: string;
  /** A calendar date includes that whole day; a timestamp is strictly before it. */
  readonly dueBefore?: IsoTimestamp | IsoDate;
  /** Archived issues alongside live ones. */
  readonly includeArchived?: boolean;
  /** Archived issues and nothing else. */
  readonly archivedOnly?: boolean;
}

export interface IssueWithRelations {
  readonly issue: Issue;
  readonly labels: readonly IssueLabel[];
  readonly commentCount: number;
  readonly attachmentCount: number;
}

/** One column of the kanban board; the board is an ordered list of these. */
export interface IssueBoardColumn {
  readonly status: IssueStatus;
  readonly issues: readonly Issue[];
  readonly total: number;
}

