/**
 * The URL is the single source of truth for the issue list filter: a filtered
 * view has to be shareable and survive a reload, and the server component that
 * renders the page parses the very same query string. These two functions are
 * that codec, kept pure so both sides can use them.
 *
 * The vocabulary is ADR 0009, shared with `issueFilterSchema` and the issue
 * repository. `assignee=none` is the sanctioned spelling of "unassigned" and
 * `assignee=me` / `author=me` of "the signed-in user" (resolved by the
 * service); an absent parameter means "don't filter on it at all", which is a
 * different query.
 */
import { issueDueBeforeSchema } from "@/schemas/issue";
import type { LabelId, ProjectId, UserId } from "@/types/common";
import {
  CURRENT_USER_TOKEN,
  ISSUE_PRIORITIES,
  UNASSIGNED_TOKEN,
  expandIssueStatuses,
  isIssueStatusFilterValue,
  type IssueFilter,
  type IssuePriority,
} from "@/types/issue";

export { CURRENT_USER_TOKEN, UNASSIGNED_TOKEN };

/** `archived=1`: archived issues alongside live ones. */
export const ARCHIVED_INCLUDED_TOKEN = "1";
/** `archived=only`: archived issues and nothing else. */
export const ARCHIVED_ONLY_TOKEN = "only";

export interface ReadableParams {
  get(name: string): string | null;
}

/**
 * Adapts a Next.js `searchParams` record so pages read it through this codec
 * rather than by hand. A repeated parameter reads as one comma list.
 */
export function searchParamsRecord(
  record: Readonly<Record<string, string | readonly string[] | undefined>>,
): ReadableParams {
  return {
    get(name) {
      const value = record[name];
      if (value === undefined) return null;
      return typeof value === "string" ? value : value.join(",");
    },
  };
}

function splitList(raw: string | null): readonly string[] {
  if (raw === null || raw.length === 0) return [];
  return raw
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

export function parseIssueFilterParams(params: ReadableParams): IssueFilter {
  // Groups (`open`, `closed`) expand to their members; unknown values drop.
  const statuses = expandIssueStatuses(
    splitList(params.get("status")).filter(isIssueStatusFilterValue),
  );
  const priorities = splitList(params.get("priority")).filter(
    (value): value is IssuePriority =>
      ISSUE_PRIORITIES.includes(value as IssuePriority),
  );
  const labelIds = splitList(params.get("label")) as readonly LabelId[];
  const project = params.get("project");
  const assignee = params.get("assignee");
  const author = params.get("author");
  const query = params.get("q");
  const dueBefore = issueDueBeforeSchema.safeParse(params.get("due_before"));
  const archived = params.get("archived");

  const filter: IssueFilter = {
    ...(project !== null ? { projectId: project as ProjectId } : {}),
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(priorities.length > 0 ? { priority: priorities } : {}),
    ...(assignee !== null
      ? {
          assigneeId:
            assignee === UNASSIGNED_TOKEN
              ? null
              : assignee === CURRENT_USER_TOKEN
                ? CURRENT_USER_TOKEN
                : (assignee as UserId),
