 * Builds the shared predicate list behind `listIssues` and its count, so the
 * reported total is always the number of rows the filter matches. The filter
 * vocabulary is ADR 0009; `me` must already be resolved by the service.
 */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const scope: ArchiveScope = wantsArchivedOnly(input)
    ? { archivedOnly: true }
    : shouldFilterArchived(input)
      ? {}
      : { includeArchived: true };
  const statuses = expandIssueStatuses(input.status ?? []);

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    statuses.length === 0 ? undefined : inArray(issues.status, statuses),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    // `undefined` does not narrow; `null` is "unassigned".
    input.assigneeId === undefined
      ? undefined
      : input.assigneeId === null
        ? isNull(issues.assigneeId)
        : eq(issues.assigneeId, input.assigneeId),
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    input.dueBefore === undefined
      ? undefined
      : dueBeforePredicate(input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    labelsPredicate(input.orgId, input.labelIds ?? []),
  );
}

/**
 * Issues due strictly before the bound `dueBeforeBound` derives (a calendar
 * date includes its whole day). The stored value is normalised to the same
 * millisecond ISO form as the bound so the text comparison is chronological;
 * issues without a due date never match.
 */
function dueBeforePredicate(value: IsoTimestamp | IsoDate): SQL {
  return and(
    isNotNull(issues.dueAt),
    sql`strftime('%Y-%m-%dT%H:%M:%fZ', ${issues.dueAt}) < ${dueBeforeBound(value)}`,
  ) as SQL;
}

/** All-of: an issue matches only when it carries every listed label. */
function labelsPredicate(
  orgId: OrgId,
  labelIds: readonly LabelId[],
): SQL | undefined {
  const wanted = [...new Set(labelIds)];
  if (wanted.length === 0) return undefined;

  return inArray(
    issues.id,
    getDb()
      .select({ id: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.labelId, wanted),
        ),
      )
      .groupBy(issueLabels.issueId)
      .having(eq(countDistinct(issueLabels.labelId), wanted.length)),
  );
}
