  console.log(issueFilterToParams(parseIssueFilterParams(new URLSearchParams("archived=only&due_before=2026-03-02"))));
  console.log(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["open", "nonsense"] }).success, issueFilterSchema.safeParse({ orgId: t.org.id, status: ["closed"], assigneeId: "none" }).data);
